INSERT INTO course_schedules (
  course_name, course_slug, course_type, start_date, end_date,
  start_time, end_time, timezone, format, duration,
  instructor_name, instructor_image, price, original_price, currency,
  total_registrants, total_seats, language, exam_included, status, is_weekend
)
SELECT
  nr.course_name, nr.course_slug, nr.course_type, nr.start_date, nr.end_date,
  nr.start_time, nr.end_time, nr.timezone, nr.format, nr.duration,
  nr.instructor_name, nr.instructor_image, nr.price, nr.original_price, nr.currency,
  nr.total_registrants, nr.total_seats, nr.language, nr.exam_included, nr.status, nr.is_weekend
FROM new_rows nr
WHERE NOT EXISTS (
  SELECT 1 FROM course_schedules cs
  WHERE cs.course_slug = nr.course_slug
    AND (cs.start_date AT TIME ZONE 'America/New_York')::date = (nr.start_date AT TIME ZONE 'America/New_York')::date
    AND cs.start_time = nr.start_time
    AND cs.status = 'active'
);
